using System;using GunmageddonAudio;
public static class DP127PolicyTests {static int checks;static void Check(bool b){checks++;if(!b)throw new Exception("DP127 policy failed");}public static void Main(){Check(!DP127Policy.InRange(299.99*299.99));Check(DP127Policy.InRange(300*300));Check(DP127Policy.InRange(15000d*15000));Check(!DP127Policy.InRange(15000.01*15000.01));Check(!DP127Policy.InRange(double.NaN));Check(!DP127Policy.InRange(double.PositiveInfinity));Check(DP127Policy.Score(true,false,5000,0,0,false)>DP127Policy.Score(false,true,5000,0,1000,false));Check(DP127Policy.Score(false,true,5000,100,0,false)>DP127Policy.Score(false,true,5000,-100,0,false));Console.WriteLine("DP127PolicyTests passed: "+checks);}}